# Define the integrate_function wrapper
@ctypes.CFUNCTYPE(ctypes.c_int, ctypes.POINTER(ctypes.c_double), ctypes.POINTER(ctypes.c_double), ctypes.POINTER(ctypes.c_double), ctypes.POINTER(ctypes.c_void_p), ctypes.POINTER(ctypes.c_double), ctypes.POINTER(ctypes.c_size_t))
def integrate_function_wrapper(x, fval, params):
    func = ctypes.cast(params.contents.func_ptr, ctypes.CFUNCTYPE(ctypes.c_int, ctypes.POINTER(ctypes.c_double), ctypes.POINTER(ctypes.c_double))).from_address(int(params.contents.func_ptr.value))
    x_val = ctypes.c_double.from_buffer_copy(x)
    fval[0] = func(ctypes.byref(x_val)).contents.f
    return 0

# Define the integrate_function function
@ctypes.CFUNCTYPE(ctypes.c_int, ctypes.POINTER(GSLFunction), ctypes.c_double, ctypes.c_double, ctypes.c_double, ctypes.c_double, ctypes.c_size_t, ctypes.POINTER(ctypes.c_double), ctypes.POINTER(ctypes.c_double), ctypes.POINTER(CQuadWorkspace))
def integrate_function(func_ptr, a, b, epsabs, epsrel, workspace_size, result, abserr, workspace):
    func = GSLFunction.from_address(int(func_ptr.value))
    func_obj = ctypes.cast(ctypes.addressof(func.__class__.__dict__['my_func']), ctypes.POINTER(ctypes.c_void_p)).contents
    func_ptr.contents.func_ptr = ctypes.byref(func_obj)
    result[0] = 0.0
    abserr[0] = 0.0
    status = gsl.gsl_integration_qags(integrate_function_wrapper, a, b, epsabs, epsrel, workspace_size, gsl.GSL_INTEG_GAUSS31, ctypes.byref(workspace.workspace), result, abserr)
    return status

gsl.gsl_integration_qags.restype = ctypes.c_int

