class GSLFunction:
    def __init__(self, func):
        self.func = func
        self.callback = ctypes.CFUNCTYPE(ctypes.c_double, ctypes.c_double)(self.call)

    def call(self, x):
        return self.func(x)

class CQuadWorkspace:
    def __init__(self, size):
        self.size = size
        self.workspace = gsl.gsl_integration_cquad_workspace_alloc(self.size)

    def __del__(self):
        gsl.gsl_integration_cquad_workspace_free(self.workspace)

def integrate_function(func, a, b, epsabs, epsrel, workspace_size):
    func_obj = GSLFunction(func)
    result = ctypes.c_double()
    abserr = ctypes.c_double()
    neval = ctypes.c_ulong()
    gsl.gsl_integration_cquad(func_obj.callback, a, b, epsabs, epsrel,
                             func_obj.workspace, ctypes.byref(result),
                             ctypes.byref(abserr), ctypes.byref(neval))
    return result.value, abserr.value, neval.value

