class GSLVector:
    def __init__(self, data):
        self.data = (ctypes.c_double * len(data))(*data)
        self.size = len(data)

    def __getitem__(self, index):
        return self.data[index]

    def __setitem__(self, index, value):
        self.data[index] = value

    def __len__(self):
        return self.size

def vector_add(a, b):
    if len(a) != len(b):
        raise ValueError("Vectors must be of the same length")
    result = GSLVector([0.0] * len(a))
    gsl.gsl_vector_memcpy(result.data, a.data)
    gsl.gsl_vector_add(result.data, b.data)
    return [result[i] for i in range(len(result))]

