def prime_factors(num):
    n = num
    factors = []
    while n % 2 == 0:
        factors.append(2)
        n //= 2
    for i in range(3, int(n**0.5)+1, 2):
        while n % i == 0:
            factors.append(i)
            n //= i
    if n > 2:
        factors.append(n)
    return factors
def fft_factorize(n):
    return prime_factors(n), len(prime_factors(n))
n = int(input())
factors, count = fft_factorize(n)
print(f"Factors: {factors}\nCount: {count}")

