gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")
def copy_matrix_gsl(source, destination):
    source_arr = (ctypes.c_double * len(source) * len(source[0]))()
    dest_arr = (ctypes.c_double * len(destination) * len(destination[0]))()
    for i in range(len(source)):
        for j in range(len(source[i])):
            source_arr[i*len(source[0])+j] = source[i][j]
    gsl.gsl_matrix_memcpy(ctypes.byref(dest_arr), ctypes.byref(gsl.gsl_matrix_view_array(source_arr, len(source), len(source[0])).matrix))
    for i in range(len(destination)):
        for j in range(len(destination[i])):
            destination[i][j] = dest_arr[i*len(destination[0])+j]
    return destination

