        return matrix.ctypes.data_as(ctypes.POINTER(ctypes.c_double))

    def numpy_to_gsl_vector(vector):
        return vector.ctypes.data_as(ctypes.POINTER(ctypes.c_double))

    U_ptr = numpy_to_gsl_matrix(U)
    D_ptr = numpy_to_gsl_matrix(D)
    Y_ptr = numpy_to_gsl_matrix(Y)
    T_ptr = numpy_to_gsl_matrix(T)

    gsl.gsl_linalg_QR_UD_decomp(ctypes.c_int(U.shape[0]), ctypes.c_int(U.shape[1]), U_ptr, D_ptr, Y_ptr, T_ptr)

