from numpy import asarray, c_double
class GSLMatrix:
    def __init__(self, array):
        self.matrix = c_double * (array.size)(*(array.flatten()))
class GSLVector:
    def __init__(self, array):
        self.vector = c_double * array.size(*array)
def numpy_to_gsl_matrix(matrix): return GSLMatrix(matrix)
def numpy_to_gsl_vector(vector): return GSLVector(vector)
