qr_ud_decomp = gsl.gsl_linalg_QR_UD_decomp
def qr_decomposition(U, D, Y, T):
    U = numpy_to_gsl_matrix(asarray(U, dtype=float))
    D = numpy_to_gsl_vector(asarray(D, dtype=float))
    Y = numpy_to_gsl_matrix(asarray(Y, dtype=float))
    T = numpy_to_gsl_matrix(asarray(T, dtype=float))
    qr_ud_decomp(U.matrix, D.vector, Y.matrix, T.matrix)
    return Y.matrix[:], T.matrix[:]

