#include <gsl/gsl_stats_double.h>
#include <gsl/gsl_sort_double.h>

#define N 10000

gsl_rng *rng;
double data[N];

gsl_rstat_workspace *w;

void init() {
    rng = gsl_rng_alloc(gsl_rng_taus);
    gsl_rng_set(rng, time(0));
    for (int i = 0; i < N; ++i) {
        data[i] = gsl_ran_rayleigh(rng, 1.0);
    }
    w = gsl_rstat_workspace_alloc(N);
}

void compute_quantiles() {
    double sorted_data[N];
    memcpy(sorted_data, data, N * sizeof(double));
    gsl_sort_double(sorted_data, 1, N);

    for (double q : {0.25, 0.50, 0.75}) {
        double q_val = gsl_stats_quantile_from_sorted_data(N, sorted_data, q);
        double error = gsl_rstat_wmean_error(w);
        printf("Quantile %.2f: %f, Error: %f\n", q, q_val, error);
    }
}

void cleanup() {
    gsl_rng_free(rng);
    gsl_rstat_workspace_free(w);
}

int main() {
    init();
    compute_quantiles();
    cleanup();
    return 0;
}

