def extract_matrix(matrix):
    rows = matrix.contents.rows
    cols = matrix.contents.cols
    data = (ctypes.c_double * (rows * cols)).from_address(gsl.gsl_matrix_ptr(matrix))
    return [[data[i * cols + j] for j in range(cols)] for i in range(rows)]

def apply_givens_qr(M, N, Q, R, i, j, c, s):
    gsl.M = create_gsl_matrix(len(M), len(M[0]))
    gsl.R = create_gsl_matrix(len(R), len(R[0]))
    for k in range(len(Q)):
        for l in range(len(Q[k])):
            gsl.gsl_matrix_set(gsl.M, k, l, Q[k][l])
    for k in range(len(R)):
        for l in range(len(R[k])):
            gsl.gsl_matrix_set(gsl.R, k, l, R[k][l])

    gsl.apply_givens_qr(gsl.M, gsl.N, gsl.Q, gsl.R, i, j, c, s)

    Q = extract_matrix(gsl.Q)
    R = extract_matrix(gsl.R)

    return Q, R

