class gsl_permutation:
    def __init__(self, n):
        self.perm = gsl.gsl_permutation_calloc(n)
        if not self.perm:
            return []
        self.size = n

    def get_data(self):
        data = (ctypes.c_size_t * self.size)()
        ctypes.memmove(data, self.perm.data, self.size * ctypes.sizeof(ctypes.c_size_t))
        return list(data)

    def __del__(self):
        if hasattr(self, 'perm') and self.perm:
            gsl.gsl_permutation_free(self.perm)

