def integrate_function(f, a, b, epsabs, epsrel, limit):
    f_ptr = ctypes.CFUNCTYPE(ctypes.c_double, ctypes.c_double, ctypes.POINTER(ctypes.c_double))(f)
    result = ctypes.c_double()
    abserr = ctypes.c_double()
    workspace = gsl.gsl_integration_workspace_alloc(limit)

