    workspace_size = 1000
    result_ptr = ctypes.c_double()
    abserr_ptr = ctypes.c_double()
    w = gsl.gsl_integration_workspace_alloc(workspace_size)
    if not w:
        raise RuntimeError("Failed to allocate GSL workspace")
    try:
        status = gsl.gsl_integration_qags(f.callback, a, b, epsabs, epsrel, limit, workspace_size, ctypes.byref(result_ptr), ctypes.byref(abserr_ptr))
        if status != 0:
            raise RuntimeError("GSL integration failed with status: {}".format(status))
    finally:
        gsl.gsl_integration_workspace_free(w)
    return result_ptr.value, abserr_ptr.value

