import ctypes
import numpy as np

class GSLMatrix:
    def __init__(self, matrix):
        self.rows = len(matrix)
        self.cols = len(matrix[0])
        self.data = (ctypes.c_double * (self.rows * self.cols))()
        for i in range(self.rows):
            for j in range(self.cols):
                self.data[i * self.cols + j] = matrix[i][j]

    def __del__(self):
        ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so").gsl_matrix_free(ctypes.byref(self.gsl_matrix))

    @property
def gsl_matrix(self):
        return self._create_gsl_matrix()

    def _create_gsl_matrix(self):
        gsl_matrix = ctypes.c_void_p()
        gsl_cblas_dgemm(0, 1, self.rows, self.cols, 1, self.data,
                      self.cols, self.data, self.cols, 0,
                      ctypes.byref(gsl_matrix), self.cols)
        return gsl_matrix

    @staticmethod
def matrix_to_gsl(matrix):
        return GSLMatrix(matrix)

def gsl_matrix_to_numpy(gsl_matrix, rows, cols):
    return np.ctypeslib.as_array((gsl_matrix.contents.data), shape=(rows, cols))

def compute_matrix_exponential(matrix, mode):
    try:
        if len(matrix) != len(matrix[0]):
            raise ValueError("Input matrix must be square")

        gsl_matrix = GSLMatrix.matrix_to_gsl(matrix)
        result_gsl_matrix = gsl_matrix._create_gsl_matrix()
        gsl_exponential = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so").gsl_linalg_exponential_ss
        gsl_exponential.argtypes = [ctypes.POINTER(GSLMatrix), ctypes.c_int, ctypes.POINTER(ctypes.c_double)]
        result_array = np.zeros((gsl_matrix.rows, gsl_matrix.cols), dtype=np.float64)
        gsl_result_ptr = result_array.ctypes.data_as(ctypes.POINTER(ctypes.c_double))

        gsl_exponential(ctypes.byref(gsl_matrix.gsl_matrix), mode, gsl_result_ptr)
        return gsl_matrix_to_numpy(result_gsl_matrix, gsl_matrix.rows, gsl_matrix.cols)
    except Exception as e:
        print(f"An error occurred: {e})
        return None

