class GSLMultifitNLinearFDF:
    def __init__(self, n, p, fcn):
        self.f = fcn
        self.n = n
        self.p = p
        self.df = None

    def function(self, params, f):
        return self.f.function(params, f)

    def dfunct(self, params, J):
        return self.f.dfunct(params, J)

def gsl_multifit_nlinear_df(h, fdtype, x, wts, f, n, p):
    GSL_x = GSLVector(x)
    GSL_wts = GSLVector(wts)
    GSL_f = GSLVector(f)

    GSL_J = GSLMatrix([[] for _ in range(n)], n, p)

    gsl_multifit_nlinear_fdf_fcn = ctypes.CFUNCTYPE(None, ctypes.POINTER(GSLMultifitNLinearFDF), ctypes.POINTER(GSLVector), ctypes.POINTER(GSLVector))
    gsl_multifit_nlinear_df_fcn_wrapper = gsl_multifit_nlinear_fdf_fcn(lambda fdf, params, f: fdf.function(params, f))

    gsl_multifit_nlinear_df_dfd_fcn = ctypes.CFUNCTYPE(None, ctypes.POINTER(GSLMultifitNLinearFDF), ctypes.POINTER(GSLVector), ctypes.POINTER(GSLMatrix))
    gsl_multifit_nlinear_df_dfd_fcn_wrapper = gsl_multifit_nlinear_df_dfd_fcn(lambda fdf, params, J: fdf.dfunct(params, J))

    gsl_multifit_nlinear_fdf_struct = ctypes.c_void_p()
    gsl.gsl_multifit_nlinear_fdf_init(ctypes.byref(gsl_multifit_nlinear_fdf_struct), n, p, gsl_multifit_nlinear_df_fcn_wrapper, gsl_multifit_nlinear_df_dfd_fcn_wrapper)

    gsl_multifit_nlinear_workspace_struct = ctypes.c_void_p()
    gsl.gsl_multifit_nlinear_alloc(ctypes.c_char_p(b"levenberg-marquardt"), n, p, ctypes.byref(gsl_multifit_nlinear_workspace_struct))

    gsl_multifit_nlinear_solve(gsl_multifit_nlinear_workspace_struct, gsl_multifit_nlinear_fdf_struct, GSL_x.data, GSL_wts.data, ctypes.c_double(h), fdtype)

    for i in range(n):
        for j in range(p):
            GSL_J.data[i][j] = gsl_multifit_nlinear_jacobian(gsl_multifit_nlinear_workspace_struct)[i * p + j]

    return [[GSL_J.data[i][j] for j in range(p)] for i in range(n)]

