c_types = {
    'gsl_matrix': gsl.gsl_matrix,
    'gsl_vector': gsl.gsl_vector
}

def matrix_to_gsl(matrix):
    M, N = len(matrix), len(matrix[0])
    data = (ctypes.c_double * (M * N))()
    for i in range(M):
        for j in range(N):
            data[i * N + j] = matrix[i][j]
    return c_types['gsl_matrix'](data, M, N)

def vector_to_gsl(vector):
    N = len(vector)
    data = (ctypes.c_double * N)()
    for i in range(N):
        data[i] = vector[i]
    return c_types['gsl_vector'](data, N)

def gsl_matrix_to_list(matrix):
    M = matrix.size1
    N = matrix.size2
    result = [[0] * N for _ in range(M)]
    for i in range(M):
        for j in range(N):
            result[i][j] = matrix.data[i * N + j]
    return result

def gsl_vector_to_list(vector):
    N = vector.size
    result = [0] * N
    for i in range(N):
        result[i] = vector.data[i]
    return result

def ql_decomposition_and_unpack(A, tau):
    M, N = len(A), len(A[0])
    A_gsl = matrix_to_gsl(A)
    tau_gsl = vector_to_gsl(tau)
    gsl.gsl_linalg_QL_decomp(A_gsl, tau_gsl)
    Q = gsl_matrix_to_list(A_gsl)
    L = [[A[i][j] if i >= j else 0 for j in range(N)] for i in range(M)]
    return Q, L

