        for i in range(self.n**2):
            self.data[i] = matrix[i // self.n][i % self.n]

    def is_positive_definite(self):
        ptr_data = ctypes.byref(self.data)
        return gsl.gsl_linalg_cholesky_decomp(ptr_data, self.n) == 0

    def cholesky_decomp(self):
        if not self.is_positive_definite():
            raise ValueError('Matrix is not positive definite')
        ptr_data = ctypes.byref(self.data)
        gsl.gsl_linalg_cholesky_decomp(ptr_data, self.n)
        result = [[0.0 for _ in range(self.n)] for _ in range(self.n)]
        for i in range(self.n):
            for j in range(i + 1):
                result[i][j] = self.data[i * self.n + j]
        return result

