class GslRstatQuantileWorkspace:
    def __init__(self, size):
        self.size = size
        self.workspace_ptr = gsl.gsl_rstat_quantile_alloc(size)
        if not self.workspace_ptr:
            raise MemoryError("Failed to allocate quantile workspace")

    def reset(self):
        gsl.gsl_rstat_quantile_reset(self.workspace_ptr)

    def add(self, value):
        gsl.gsl_rstat_quantile_add(self.workspace_ptr, ctypes.c_double(value))

    def get_quantile(self, p):
        if p < 0 or p > 1:
            raise ValueError("Quantile must be between 0 and 1")
        result = gsl.gsl_rstat_quantile_get(self.workspace_ptr, ctypes.c_double(p))
        return float(result)

    def free(self):
        gsl.gsl_rstat_quantile_free(self.workspace_ptr)

def compute_quantile(p, values):
    if not (0 <= p <= 1):
        raise ValueError("Quantile must be between 0 and 1")

    workspace = GslRstatQuantileWorkspace(len(values))
    try:
        for value in values:
            workspace.add(value)
        return workspace.get_quantile(p)
    finally:
        workspace.free()

